    for c in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            color, start = grid[r][c], r
            while r < h and grid[r][c] == color:
                r += 1
            if r - start >= 2:
                bars.append(("v", c, start, r, color))

    bar_cells = set()
    for axis, fixed, start, end, _ in bars:
        if axis == "h":
            bar_cells.update((fixed, c) for c in range(start, end))
        else:
            bar_cells.update((r, fixed) for r in range(start, end))
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in bar_cells]
    if not bars or not markers:
        return out

    mr, mc, ray_color = markers[0]
    for axis in ("h", "v"):
        same_axis = [bar for bar in bars if bar[0] == axis]
        if not same_axis:
            continue
        marker_coord = mc if axis == "h" else mr
        # The bar containing the marker determines its offset; corresponding
        # bars on the opposite edge launch at that same relative offset.
        anchor = next((bar for bar in same_axis
                       if bar[2] <= marker_coord < bar[3]), same_axis[0])
        offset = marker_coord - anchor[2]
        for _, fixed, start, end, _ in same_axis:
            pos = start + offset
            if pos >= end:
                continue
            if axis == "h":
                dr = 1 if fixed == 0 else -1
                r, c = fixed + dr, pos
                while 0 <= r < h:
                    if (r, c) == (mr, mc):
                        out[r][c] = 4
                        break
                    if grid[r][c] != bg:
                        break
                    out[r][c] = ray_color
                    r += dr
